import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        Main program = new Main();
        program.launch();
    }

    private void launch() throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);
        Challenge solver = new Challenge();
        solver.compute(1, scanner, printer);
        printer.close();
    }

    static class Challenge {
        private static final long MOD = 998244353L;
        private long[] fact;
        private long[] invFact;

        private long modPow(long base, long exponent) {
            long res = 1L;
            base %= MOD;
            while (exponent > 0) {
                if ((exponent & 1) == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exponent >>= 1;
            }
            return res;
        }

        public void compute(int tc, FastScanner in, FastPrinter out) {
            int MAX = 200001;
            fact = new long[MAX];
            invFact = new long[MAX];
            fact[0] = invFact[0] = 1L;
            for (int i = 1; i < MAX; i++) {
                fact[i] = fact[i - 1] * i % MOD;
                invFact[i] = invFact[i - 1] * modPow(i, MOD - 2) % MOD;
            }

            int n = in.nextInt();
            long k = in.nextLong();

            if (k >= n) {
                out.println(0);
                return;
            }
            if (k == 0) {
                out.println(fact[n]);
                return;
            }

            int m = n - (int)k;
            long sum = 0L;
            for (int i = 0; i <= m; i++) {
                long term = nChooseK(m, i) * modPow(m - i, n) % MOD;
                sum = (i % 2 == 0) ? (sum + term) % MOD : (sum - term + MOD) % MOD;
            }

            long result = 2L * fact[n] % MOD;
            result = result * invFact[n - m] % MOD;
            result = result * sum % MOD;
            result = result * invFact[m] % MOD;
            out.println(result);
        }

        private long nChooseK(int n, int k) {
            return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
        }
    }

    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }

    static class FastPrinter {
        private PrintWriter writer;

        public FastPrinter(OutputStream stream) {
            writer = new PrintWriter(stream, true);
        }

        public void println(long value) {
            writer.println(value);
        }

        public void close() {
            writer.close();
        }
    }
}
